-- PRIVACY 1.7, REFUND 1.9 AND DISCLAIMER 1.4: THE PDPL GROUNDS, THE AUTOMATED DECISIONS, ONE LIABILITY LIMIT.
--
-- Agent: ceo. 19 Oct 2026. Legal risk review of 19 Oct 2026 (findings 1, 3, 5, 6, 10, 11) and the founder corrections of
-- the same day (no promise of review by a person; an objection goes through customer_support, then the ceo seat).
-- GENERATED from src/content/legal.json by the body rule of the_signed_legal_registry_follows_the_14_september_texts.sql
-- (the English page <div class="body"> content). The rule re-derives privacy 1.6 byte-for-byte to its file (checked
-- 19 Oct 2026). Article numbers were read on uaelegislation.gov.ae on 19 Oct 2026: PDPL Arts 4, 5, 6, 18, 22, 23;
-- Commercial Transactions Law Art. 92; FDL 14/2023 Art. 6(6)-(7).
--   * privacy 1.7: "legitimate interests" (which the PDPL does not provide) replaced by the Art. 4 grounds; automated
--     decisions are agreed in the contract (Art. 18(2)(a)) and an objection goes to Customer Support; the five-year
--     retention gains the Art. 92 claims ground; promotions need a separate unticked box; invitations rest on Art. 4
--     (data the business published; ledger 1265: all eligible leads); the transfer register is named.
--   * refund 1.9: the leftover card-fee wording ("Both amounts", "either") is gone; "the CEO" decides nothing: QuotesDone
--     decides under its published rules, and the final contact attempt is made by the QuotesDone operations team.
--   * disclaimer 1.4: a revealed quotation binds the supplier (Supplier Agreement cl.12); the liability limit is Terms cl.9.
-- Nobody signs these three documents, so each is a new version with an on-page change notice, not a re-acceptance.
-- No begin/commit: the applier runs the file as one transaction.
--   node scripts/apply_sql.mjs scripts/sql/privacy_1_7_refund_1_9_and_disclaimer_1_4_name_the_lawful_grounds_and_one_liability_limit.sql --apply --ddl --seat ceo

-- THE SUPERSEDED TEXTS STAY IN THE REGISTRY, BYTE-IDENTICAL (release review of #1517). Before any body is replaced,
-- each live row is copied to <slug>-v<version> (category archived, source archived:<slug>), only if it is still the
-- version being superseded; a re-run inserts nothing. Customer Terms v10 and Supplier Agreement v15 are copied here
-- too, so this file must be applied BEFORE the_terms_of_19_october_2026_make_promotions_opt_in_and_name_the_automated_decisions.sql.
insert into public.legal_documents (slug, title, category, version, effective_date, summary, body_html, updated_at, content_sha256, source)
select d.slug || '-v' || ltrim(d.version, 'v'), d.title, 'archived', d.version, d.effective_date, d.summary, d.body_html, now(),
       encode(sha256(convert_to(d.body_html, 'UTF8')), 'hex'), 'archived:' || d.slug
  from public.legal_documents d
 where (d.slug, d.version) in (('privacy', '1.6'), ('refund-policy', '1.8'), ('disclaimer', '1.3'), ('customer-terms', 'v10'), ('supplier-agreement', 'v15'))
on conflict (slug) do nothing;

update public.legal_documents set body_html = $qd_privacy$<h1>Privacy Policy</h1><div class="muted">How QuotesDone Technologies collects, uses, shares and protects personal data on the QuotesDone anonymous quotation marketplace, and your rights under UAE Federal Decree-Law No. 45 of 2021 (the Personal Data Protection Law).</div><div class="card"><p><strong>What changed in version 1.7 (19 October 2026):</strong> each purpose now names the ground the PDPL allows for it, in place of "legitimate interests", which the PDPL does not provide (section 3); automated decisions are part of the service you agree to, and an objection goes through our support channel (section 4); a second ground is given for the five-year retention period (section 7); promotional messages need a separate box you tick yourself, and business invitations rest on the contact details the business itself published (section 9).</p></div><div class="card"><h2>1. Who We Are (Data Controller)</h2><p>This Privacy Policy explains how we handle your personal data when you use QuotesDone, an online B2B anonymous quotation marketplace.</p><p>The data controller is:</p><ul><li>QuotesDone Technologies, a Dubai Sole Establishment</li><li>DET Dubai Trader License No. 1633275</li><li>Owner: Ahmad Mhd Nabil Alzain</li><li>Address: Dubai, United Arab Emirates</li><li>Email: management@quotesdone.com; Phone: +971 50 931 9355 (the number on our licence record is +971 56 791 8605)</li></ul><p>We process personal data in accordance with the UAE Personal Data Protection Law, Federal Decree-Law No. 45 of 2021 (PDPL), and its implementing regime overseen by the UAE Data Office, which from June 2026 operates within the new UAE Federal Authority for Artificial Intelligence and Data. This policy applies to customers, suppliers and visitors. Where you act on behalf of a business, references to your personal data mean the personal data of the individuals concerned.</p><h2>2. Personal Data We Collect</h2><p>Depending on how you use the platform, we collect:</p><ul><li>Customer identity and contact data: your name, email address and mobile number, with the mobile number verified by one-time password (OTP).</li><li>Request content: the job or request you submit as text, voice recordings, photographs or drawings, including any personal data you choose to include.</li><li>Supplier data: business details and Know Your Customer (KYC) documents provided for vetting and onboarding.</li><li>Payment data: a payment reference returned by our payment processor, Stripe. We do not store full card numbers; card and Apple Pay details are handled by Stripe, which is certified to the Payment Card Industry Data Security Standard (PCI DSS).</li><li>Usage and technical data: logs, device and connection information, and records of platform activity.</li></ul><p>We do not intentionally collect special categories of data. Please avoid including sensitive details in request content unless necessary.</p><h2>3. Purposes and Lawful Bases</h2><p>We process personal data for clear purposes, each supported by a lawful basis under the PDPL:</p><ul><li>To create and manage your account, verify your mobile by OTP, and provide the marketplace, including matching requests to suppliers and enabling paid reveals (performance of a contract).</li><li>To calculate and collect the customer Reveal Fee of 3% of the quoted value at the point you choose to reveal a supplier, and to keep accounting records (performance of a contract and legal obligation). Suppliers pay no commission or success fee on jobs they win.</li><li>To vet suppliers and verify their KYC documents (performance of the Supplier Agreement, which the supplier asks us to enter into), and to prevent fraud and misuse and secure the platform (compliance with our legal obligations, and the establishment, exercise or defence of legal claims).</li><li>To share a chosen supplier&#x27;s contact details on a paid reveal, and for optional marketing (your consent, which you may withdraw at any time).</li></ul><p>The PDPL does not provide a general "legitimate interests" ground, and we do not rely on one. Where we process personal data without your consent, we rely only on the cases Article 4 of the PDPL permits, as listed above.</p><h2>4. Smart and Automated Processing</h2><p>QuotesDone uses smart and automated tools to operate the marketplace. These tools:</p><ul><li>Structure and standardise the requests you submit (including converting voice, photos and drawings into a structured brief).</li><li>Match each request to suppliers in the matching trade who are likely to be able to quote.</li><li>Summarise requests and quotes to make them easier to compare.</li></ul><p>Some decisions on the platform are made by automated systems, including software that uses large language models, without a person reviewing each case. They include matching and ranking suppliers, checking quotes against your specifications, and assessing refund requests and disputes under our published rules. You remain free to accept, reject or ignore any quote. These decisions are part of the service you contract for, and you agree to them when you accept our Terms of Service (clause 10) or the Supplier Agreement (clause 27). Under Article 18(2)(a) and (c) of the Personal Data Protection Law, the right to object to a decision resulting from automated processing does not apply where the automated processing is agreed in the contract between you and QuotesDone, or where you have given your prior consent to it. You may still object to, or complain about, any decision through the Platform or at management@quotesdone.com: QuotesDone Customer Support handles it and, if it is not resolved there, refers it to the QuotesDone operations team. Automated outputs, including summaries and comparisons, can contain errors; please check the supplier&#x27;s own quotation before relying on it.</p><h2>5. How We Share Data</h2><p>Anonymity is central to QuotesDone. We share personal data only as follows:</p><ul><li>Request content is shared with matched suppliers WITHOUT revealing your identity, so suppliers can prepare anonymised quotes.</li><li>Your contact details are disclosed to a single supplier only after you pay the Reveal Fee and consent to the reveal for that chosen supplier; suppliers receive customer contact data only for jobs revealed to them.</li><li>Our payment processor, Stripe, receives the data needed to take payment (card or Apple Pay) and returns a payment reference.</li><li>Service providers process data on our behalf, under their terms and our instructions. They are named in section 6, with what they process and where.</li></ul><p>We may also disclose data where required by UAE law, a court of competent authority, or to protect our legal rights. We do not sell personal data.</p><h2>6. Service Providers and Cross-Border Transfers</h2><p>Our platform is hosted outside the United Arab Emirates, and our service providers process personal data outside the UAE. They are:</p><ul><li>Supabase (database, file storage, sign-in and server functions): all platform data. Hosted in Singapore.</li><li>Vercel (website hosting and delivery): website requests and technical data.</li><li>OpenRouter and the model providers it routes to (such as Google and Anthropic): the text of requests, documents, quotes and messages that our automated tools read.</li><li>Resend (email delivery) and Microsoft 365 (our company mailbox): email addresses and the content of emails we send and receive.</li><li>Meta (WhatsApp Business Platform) and Twilio (text messages and verification codes): mobile numbers and message content.</li><li>Stripe (payments): the data needed to take a payment.</li><li>Dropbox (backup copies of records and documents): copies of platform records.</li><li>Serper (web search): search queries about businesses, products and prices; these do not include your contact details.</li></ul><p>Except where a location is stated above, these providers process data in the United States and in other countries where they operate. Where we transfer personal data outside the UAE, we apply the safeguards required by Articles 22 and 23 of the PDPL:</p><ul><li>We transfer data to countries the UAE Data Office recognises as providing an adequate level of protection; or</li><li>Where adequacy is not established, we rely on appropriate safeguards such as contractual terms obliging the recipient to protect the data, or on the other grounds those Articles allow, including your explicit consent, in each case in a manner that does not conflict with the public and security interests of the State.</li></ul><p>We keep a register of each provider&#39;s data processing terms and the safeguard it relies on for transfers. You may contact us for more information about the safeguards applied to a transfer.</p><h2>7. Data Retention</h2><p>We keep personal data only for as long as necessary for the purposes described above and to meet legal obligations. Article 3 of Cabinet Decision No. 74 of 2023 (the Executive Regulation of the Tax Procedures Law) requires records to be kept for five years from the end of the calendar year in which they were created. Records that have no tax relevance, such as a conversation about a request that was never revealed, are kept for the same period on a second ground: customers and suppliers deal with QuotesDone in the course of their business, and a claim between merchants about their commercial obligations may be brought within five years from the date the obligation falls due (Article 92 of the Commercial Transactions Law, Federal Decree-Law No. 50 of 2022). Keeping the record for that period allows a claim to be established or defended, which Article 4 of the PDPL permits. Our periods follow both:</p><ul><li>Account data: while your account is active, and for five years after its last activity.</li><li>Conversations with us (emails, WhatsApp messages, and portal and website chat): while your account is active, and for five years after its last activity, and in any case for five years from the end of the calendar year in which the message was written. The message text and its archived copy are then deleted.</li><li>Requests and their records (request details, drawings, bills of quantities, photographs, quotes and comparison reports): for at least five years from the end of the calendar year in which they were created.</li><li>Transaction and financial records, including Reveal Fee records: for at least five years from the end of the calendar year in which they were created, or longer where the law requires.</li><li>Supplier KYC documents: for the duration of the relationship and five years after it ends.</li><li>Records connected with an open dispute, refund, complaint or unpaid amount: until the matter is closed, even where a period above has ended.</li><li>An unfinished sign-up (an account whose email, mobile verification or acceptance of the terms was not completed within 30 minutes): deleted in full after 30 minutes, with nothing sent to it.</li><li>Backup copies of our database: 30 days of daily copies and one copy for each of the last 12 months.</li><li>Security and audit logs: for limited periods.</li></ul><p>When a retention period ends, we securely delete or irreversibly anonymise the data.</p><h2>8. Your Rights Under the PDPL</h2><p>Subject to the conditions and exceptions in the PDPL, you have the right to:</p><ul><li>Access your personal data and obtain information about how it is processed.</li><li>Request correction of inaccurate or incomplete data.</li><li>Request deletion of your data where the legal grounds apply.</li><li>Object to, or request restriction of, certain processing, including certain automated processing, within the limits of Article 18 of the PDPL (section 4).</li><li>Request that your personal data be provided to you, or transferred to another controller, in a structured, commonly used, machine-readable format (data portability), where technically feasible.</li><li>Withdraw consent at any time, without affecting processing carried out before withdrawal.</li></ul><p>To exercise any right, contact us at management@quotesdone.com. We will respond within the timeframes required by the PDPL. If you are not satisfied, you may lodge a complaint with the UAE Data Office.</p><h2>9. Electronic Marketing and Communications</h2><p>We send transactional messages you need to use the service — for example mobile one-time passwords (OTP), request and quote notifications, and account or payment confirmations — on the basis of our contract with you; these are not marketing.</p><p>We send marketing or promotional messages by email, SMS, WhatsApp or other electronic means only if you have ticked the separate box to agree to them. The box is never ticked in advance, it is not needed to use the service, and we record when you ticked it. You can withdraw consent or unsubscribe at any time using the link or instructions in the message, or by emailing management@quotesdone.com.</p><p><strong>Invitations to businesses.</strong> We invite businesses in the UAE to list as suppliers on QuotesDone. For this we use business contact details that the business itself has published, for example on its website or in a public business directory: the company name, its trade, and its published business email address. We rely on Article 4 of the PDPL, which permits the processing of data that has become available and known to all by an act of its owner: the business published this address itself. We send one invitation and up to three reminders, by email, during working hours. Every message identifies QuotesDone and contains a one-click unsubscribe link, and an unsubscribe stops every further message at once and permanently. We use this data for nothing else and we do not sell it. You may ask us at any time what we hold and where we obtained it, or ask us to delete it; we then keep only the record of your opt-out, so that we do not contact you again.</p><p>We handle electronic communications in line with the UAE telecommunications and electronic-marketing rules overseen by the Telecommunications and Digital Government Regulatory Authority (TDRA) and the Electronic Transactions and Trust Services Law (Federal Decree-Law No. 46 of 2021). We do not sell your contact details for third-party marketing.</p><h2>10. Security</h2><p>We apply appropriate technical and organisational measures to protect personal data against unauthorised access, loss, alteration or disclosure, consistent with the PDPL and the Electronic Transactions and Trust Services Law, Federal Decree-Law No. 46 of 2021.</p><ul><li>Access to personal data is restricted to authorised personnel on a need-to-know basis.</li><li>We use encryption in transit, OTP verification for customer mobile numbers, and segregation of anonymised request content from identity data.</li><li>Payment card data is handled by Stripe, our PCI DSS–certified payment processor, and is not stored by us.</li></ul><p>No system can be guaranteed to be completely secure. If a personal data breach occurs that meets the legal threshold, we will notify the UAE Data Office and affected individuals as required by the PDPL.</p><h2>11. Children, Changes and Contact</h2><p>QuotesDone is a business-to-business platform intended for users aged 18 and over. It is not directed at minors, and we do not knowingly collect personal data from children. If you believe a minor has provided us data, please contact us so we can delete it.</p><p>We may update this Privacy Policy from time to time to reflect changes in our services or the law. The current version is always available on our platform, and material changes will be notified where appropriate.</p><p>For any privacy question, to exercise your rights, or to reach our data protection contact, please use:</p><ul><li>Email: management@quotesdone.com</li><li>Phone: +971 50 931 9355 (licence record: +971 56 791 8605)</li><li>Post: QuotesDone Technologies, Dubai, United Arab Emirates (our DET Trader License is for an online business with no shop front, so there is no street address)</li></ul><p>This policy is governed by the laws of the UAE, and disputes are subject to the courts of Dubai.</p></div>$qd_privacy$
 where slug = 'privacy';
update public.legal_documents set version = '1.7', effective_date = date '2026-10-19',
       content_sha256 = encode(sha256(convert_to(body_html, 'UTF8')), 'hex'), updated_at = now()
 where slug = 'privacy';

update public.legal_documents set body_html = $qd_refund_policy$<h1>Refund &amp; Cancellation Policy</h1><div class="muted">Explains when the QuotesDone Reveal Fee is and is not refundable, how to request a refund, processing times and method, supplier registration-fee terms, and your preserved statutory rights under UAE Federal Law No. 15 of 2020.</div><div class="card"><p><strong>What changed in version 1.9 (19 October 2026):</strong> the Reveal Fee is stated as the single total you pay (section 2); refunds are decided by QuotesDone under these rules, the final contact attempt on day 5 is made by the QuotesDone operations team, and an objection goes to QuotesDone Customer Support (sections 3 and 6).</p></div><div class="card"><h2>1. About This Policy</h2><p>This Refund &amp; Cancellation Policy applies to QuotesDone, an online business-to-business quotation marketplace operated by QuotesDone Technologies (Dubai Sole Establishment; DET Dubai Trader License No. 1633275), Dubai, United Arab Emirates.</p><p>QuotesDone is a marketplace and facilitator only. We connect customers with suppliers and provide anonymised quotations. We are not a contractor, supplier or party to the works quoted, and this Policy governs only the fees you pay to QuotesDone, not amounts payable to a supplier under any separate contract you enter into.</p><p>This Policy must be read together with our Terms &amp; Conditions. It is governed by the laws of the UAE and applied without prejudice to your non-waivable statutory rights under Federal Law No. 15 of 2020 on Consumer Protection and its Implementing Regulation (Cabinet Resolution No. 66 of 2023).</p><h2>2. The Reveal Fee</h2><p>To unlock the identity and contact details of a chosen supplier behind an anonymised quotation, you pay a Reveal Fee equal to 3% of the quoted amount, and nothing more: no card fee or surcharge is added. No cap applies to the Reveal Fee. The Reveal Fee is the total you pay and is shown before you pay. QuotesDone is not registered for VAT, and no VAT is charged on it.</p><p>The Reveal Fee is a charge for the reveal service provided by QuotesDone. It is separate from, and additional to, any price agreed between you and the supplier for the actual goods, services or works.</p><p>Because the Reveal Fee unlocks supplier information immediately on payment, it is generally treated as earned once the reveal is delivered, subject to the specific refund right described below and to your statutory rights under UAE law.</p><h2>3. When a Reveal Is Refunded</h2><p>We refund everything you paid for a reveal in one defined circumstance: where a revealed supplier does not respond to you within five (5) working days of your payment and does not respond to QuotesDone&#39;s final contact attempt by phone, WhatsApp or email. You do not need to prove anything for the clock to start: we track every reveal from the moment you pay. If the supplier has not responded within three (3) working days, we chase the supplier on your behalf and copy you; if there is still no response on the fifth (5th) working day, the QuotesDone operations team makes a final contact attempt; if the supplier does not respond to that attempt, the refund is issued.</p><p>If you have tried to reach the supplier yourself, dated copies of emails, messages sent through the Platform, or call logs help us close the case faster, but they are not a condition of the refund. Working days are Monday to Friday, excluding UAE public holidays.</p><p>If these conditions are met, everything you paid to reveal that supplier is refunded: the Reveal Fee. The decision is made by QuotesDone under these published rules, by the QuotesDone operations team using automated tools, as you agreed in clause 10 of the Terms of Service. Whichever way it goes, it is recorded against your refund case reference and the decision reference, and both are shown to you in your account and quoted when we confirm the outcome. If you object to the decision, tell us through the Platform or at management@quotesdone.com: QuotesDone Customer Support handles your objection and, if it is not resolved there, refers it to the QuotesDone operations team. This refund right is in addition to any remedy available to you under Federal Law No. 15 of 2020 on Consumer Protection.</p><h2>4. When a Reveal Is Not Refunded</h2><p>The Reveal Fee is not refundable once the revealed supplier has responded to you within the five-working-day window, as the reveal service has then been fully delivered and the supplier has engaged.</p><p>The Reveal Fee is not refundable for a change of mind, for example where you decide not to proceed with a supplier who did respond, where you select a different supplier, or where the supplier&#x27;s pricing or terms no longer suit you.</p><p>The Reveal Fee is not refundable where the supplier responded to you or to QuotesDone within the five-working-day window. Nothing in this section limits your non-waivable rights under UAE consumer protection law where they apply.</p><h2>5. How to Request a Refund</h2><p>You do not need to submit a request for a non-response refund: the ladder above runs automatically from the moment you pay. You can still tell us at any time that the supplier is not responding, by emailing management@quotesdone.com or by using the support function on the Platform, and we will chase the supplier immediately.</p><p>If you do write to us, your account email and the reveal reference are enough. Proof of your own attempts to reach the supplier (emails, Platform messages or call logs) is optional: it can help us close the case faster, but it is never a condition of the refund (see section 3).</p><p>We may ask for further information to identify your reveal. Providing complete and accurate information helps us assess and process eligible refunds promptly.</p><h2>6. Processing Time and Method</h2><p>Once QuotesDone decides a refund, it is issued to the original payment method through our payment processor, Stripe, and we confirm it to you with your refund case reference. Banks and card issuers usually take seven (7) to fourteen (14) working days to show the refund on your statement.</p><p><b>Payments handled by Stripe · PCI DSS.</b> Your card or Apple Pay payment is processed by Stripe, a payment processor certified to the Payment Card Industry Data Security Standard; QuotesDone never sees or stores your full card number.</p><p>Refunds are made in the currency of the original payment and for everything you paid for the reveal: the Reveal Fee. QuotesDone deducts nothing from your refund and never passes the payment processor&#39;s costs to you. What QuotesDone recovers under the Supplier Agreement (the amount refunded to you, the payment processor&#39;s fee on your payment that QuotesDone could not recover, an administrative fee of AED 500, and interest at 12% per annum, or the lower amounts of the version of the Supplier Agreement the supplier had signed) is charged to the supplier whose non-response caused the refund, never to you.</p><p>If a refund cannot be returned to the original payment method for reasons outside our control, we will agree an alternative lawful method with you.</p><h2>7. Supplier Registration-Fee Terms</h2><p>Suppliers may be charged a registration fee to join and maintain a profile on the Platform. QuotesDone charges suppliers no commission, success fee or transaction fee on jobs they win. These terms apply to suppliers, not to customers.</p><p>Any supplier registration fee is charged for access to the marketplace and listing services over the registration period. Where a fee covers a defined period, it is generally non-refundable for the unused portion once access has been granted, except where required by law or expressly agreed in writing.</p><h2>8. Your Statutory Rights</h2><p>Nothing in this Policy excludes, restricts or waives any right you may have under Federal Law No. 15 of 2020 on Consumer Protection and its Implementing Regulation (Cabinet Resolution No. 66 of 2023), or under other applicable UAE law.</p><p>Where a service is not provided as described, your statutory remedies under UAE consumer protection law continue to apply alongside the contractual refund right in this Policy.</p><p>If you believe your consumer rights have not been honoured, you may contact us first and, if unresolved, escalate to the relevant authority as set out in our Complaints &amp; Dispute Resolution Policy.</p></div>$qd_refund_policy$
 where slug = 'refund-policy';
update public.legal_documents set version = '1.9', effective_date = date '2026-10-19',
       content_sha256 = encode(sha256(convert_to(body_html, 'UTF8')), 'hex'), updated_at = now()
 where slug = 'refund-policy';

update public.legal_documents set body_html = $qd_disclaimer$<h1>Disclaimer &amp; Limitation of Liability</h1><div class="muted">Confirms QuotesDone&#x27;s marketplace/intermediary status, exactly which supplier checks QuotesDone performs and the absence of warranties beyond them on quality, pricing or completion, your due-diligence responsibility, and a limitation of liability as set out in the Terms of Service, with carve-outs for fraud, gross negligence and non-waivable UAE consumer and legal rights.</div><div class="card"><p><strong>What changed in version 1.4 (19 October 2026):</strong> a Supplier is bound by its revealed quotation, and only the automated estimates and comparisons are indicative (section 3); the limit of our liability is the one in clause 9 of the Terms of Service (section 5).</p></div><div class="card"><h2>1. About This Disclaimer</h2><p>This Disclaimer &amp; Limitation of Liability applies to QuotesDone, operated by QuotesDone Technologies (Dubai Sole Establishment; DET Dubai Trader License No. 1633275), Dubai, United Arab Emirates.</p><p>It forms part of our Terms &amp; Conditions and should be read together with our Refund &amp; Cancellation Policy and Complaints &amp; Dispute Resolution Policy.</p><p>It is governed by the laws of the UAE, including Federal Law No. 15 of 2020 on Consumer Protection, the Federal Decree-Law No. 50 of 2022 on Commercial Transactions and the Civil Transactions Law (Federal Decree-Law No. 25 of 2025), and is applied subject to your non-waivable statutory rights.</p><h2>2. Marketplace / Intermediary Status</h2><p>QuotesDone is an online marketplace and intermediary that provides anonymised supplier quotations and a reveal service. We are not a contractor, supplier, agent or party to any contract for goods, services or works formed between a customer and a supplier.</p><p>Any contract for the actual goods, services or works is entered into directly between the customer and the chosen supplier, on terms agreed between them. We are not responsible for performing, supervising or guaranteeing that contract.</p><p>Our role is limited to operating the Platform and facilitating connections between customers and suppliers.</p><h2>3. No Warranty on Suppliers or Quotes</h2><p>Before a supplier can be matched, QuotesDone checks the mandatory six (business name, mobile number, email address, trade licence, company profile and signed Supplier Agreement) and, on the trade licence, the licence number, issuing authority and expiry date, as published at <a href="/how-we-verify/">How we verify suppliers</a>. That is what &quot;verified&quot; and &quot;licence-checked&quot; mean on QuotesDone. The check confirms the licence as presented on the date it was made; it does not guarantee that the licence covers your specific works.</p><p>Beyond those checks, we do not warrant or guarantee the qualifications, conduct, workmanship, solvency, insurance, quality, pricing, availability or completion of any supplier or the works they quote for.</p><p>A Supplier is bound by its revealed quotation for its scope and validity (Supplier Agreement clause 12). The final contract may change only if the scope changes by agreement between you and the Supplier. Cost estimates, price ranges and comparisons produced by the Platform&#39;s automated tools are indicative only and are not quotations.</p><p>While we take reasonable steps to operate the Platform properly, the Platform and its content are provided on an &quot;as is&quot; and &quot;as available&quot; basis to the extent permitted by UAE law.</p><h2>4. Customer Due-Diligence Responsibility</h2><p>You are responsible for carrying out your own due diligence on any supplier before entering into a contract, including confirming that their trade licence covers your specific works and checking permits, insurance, references, pricing and suitability for your requirements.</p><p>You should satisfy yourself as to the terms of any contract you enter into with a supplier and should not rely on QuotesDone to assess or approve the supplier on your behalf.</p><p>Paying the Reveal Fee unlocks supplier contact details; it is not an endorsement or recommendation of the supplier. The only verification QuotesDone performs is the one described at <a href="/how-we-verify/">How we verify suppliers</a>; everything beyond it, including whether the licence covers your specific works, permits, insurance and references, remains yours to check.</p><h2>5. Limitation of Liability</h2><p>Our liability to you is limited as set out in clause 9 of the <a href="/terms/">Terms of Service</a>.</p><h2>6. Carve-Outs and Non-Waivable Rights</h2><p>Nothing in this Disclaimer excludes or limits our liability for fraud, fraudulent misrepresentation, gross negligence or wilful misconduct, or for death or personal injury caused by our negligence, or for any other liability that cannot lawfully be excluded.</p><p>Nothing in this Disclaimer excludes, restricts or waives any non-waivable right or remedy you have under Federal Law No. 15 of 2020 on Consumer Protection and its Implementing Regulation (Cabinet Resolution No. 66 of 2023), or under other mandatory provisions of UAE law.</p><p>Where any provision of this Disclaimer is found to be unenforceable, the remaining provisions continue in full force and effect.</p></div>$qd_disclaimer$
 where slug = 'disclaimer';
update public.legal_documents set version = '1.4', effective_date = date '2026-10-19',
       content_sha256 = encode(sha256(convert_to(body_html, 'UTF8')), 'hex'), updated_at = now()
 where slug = 'disclaimer';

select case when (select count(*) from public.legal_documents a where a.slug in ('privacy-v1.6', 'refund-policy-v1.8', 'disclaimer-v1.3', 'customer-terms-v10', 'supplier-agreement-v15')
          and a.category = 'archived' and a.content_sha256 = encode(sha256(convert_to(a.body_html, 'UTF8')), 'hex')) = 5
   and (select count(*) from public.legal_documents d where d.slug = 'privacy' and d.version = '1.7' and d.effective_date = date '2026-10-19' and d.content_sha256 = 'f53efc495115cc5dc5c279ba0cc0b536d3977d59e2709e3235b4872aa5f65ad7' and encode(sha256(convert_to(d.body_html, 'UTF8')), 'hex') = 'f53efc495115cc5dc5c279ba0cc0b536d3977d59e2709e3235b4872aa5f65ad7') = 1
   and (select count(*) from public.legal_documents d where d.slug = 'refund-policy' and d.version = '1.9' and d.effective_date = date '2026-10-19' and d.content_sha256 = 'd48d5bf62f42f67421f256ec30dc8dc819ddb9d39743bb325102aa17c4141e18' and encode(sha256(convert_to(d.body_html, 'UTF8')), 'hex') = 'd48d5bf62f42f67421f256ec30dc8dc819ddb9d39743bb325102aa17c4141e18') = 1
   and (select count(*) from public.legal_documents d where d.slug = 'disclaimer' and d.version = '1.4' and d.effective_date = date '2026-10-19' and d.content_sha256 = '29cd01f06b312d3ec223ee0ea763d7f38a3cdf10ec69160207fcfd7f5eb833cc' and encode(sha256(convert_to(d.body_html, 'UTF8')), 'hex') = '29cd01f06b312d3ec223ee0ea763d7f38a3cdf10ec69160207fcfd7f5eb833cc') = 1
  then 'PROBE OK' else 'PROBE FAILED: a superseded text is not archived, or a registry row is not the site body of its new version' end as verdict;
